"""Arrange real WebGL captures with labels; no tone or shadow retouching."""
from pathlib import Path
import json,hashlib
from PIL import Image,ImageDraw,ImageFont,ImageOps
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'docs/quality-report/exposure-overlap'
NAMES={'living':'客厅','master':'主卧','kitchen':'厨房','dining':'餐厅','second':'次卧','bath':'卫生间','balcony':'阳台','storage':'储藏间','balconyBasin':'阳台台盆近景','pillow':'床品近景','kitchenCorner':'厨房转角台面','wardrobe':'衣柜近景'}
SEAMS={'wardrobeBase':'衣柜侧板与底板','kitchenJoin':'厨房转角台面','chairBoss':'餐椅支架连接','doorHeader':'入户门框转角'}
def font(n,b=False):return ImageFont.truetype('C:/Windows/Fonts/msyhbd.ttc' if b else 'C:/Windows/Fonts/msyh.ttc',n)
records={stage:json.loads((ROOT/f'validation/exposure-overlap-{stage}.json').read_text(encoding='utf-8')) for stage in ['before','after']}
assert all(r['result']=='passed' for r in records.values())
for b,a in zip(records['before']['cases'],records['after']['cases']):
    for x,y in zip(b['captures'],a['captures']):
        assert x['state']['camera']==y['state']['camera'] and x['state']['angles']==y['state']['angles'] and x['state']['fov']==y['state']['fov']
        assert x['state']['lamp']==y['state']['lamp']=='1'
        assert abs(y['state']['exposure']/x['state']['exposure']-.8)<1e-6
        # Corner closeups also change countertop coverage/material ownership.
        # Compare brightness direction on the room views, not changed geometry.
        if x['room']!='kitchenCorner':assert y['metrics']['mean']<x['metrics']['mean']
        assert y['metrics']['brightFraction']<=x['metrics']['brightFraction']+.001
manifest={'scope':__doc__,'sheets':[]}
def sheet(name,ids,time,title,diagnostic=False):
    w=800;ih=563;head=100;rowh=44+ih+12;canvas=Image.new('RGB',(1624,head+len(ids)*rowh+40),'#f2f0e9');d=ImageDraw.Draw(canvas)
    d.text((12,10),title,font=font(30,True),fill='#263b31');d.text((12,57),'左：修复前　　右：修复后　｜　'+('每个实体使用诊断色，几何和深度保持原值' if diagnostic else '同机位、同时间、灯光滑块均为100%'),font=font(20),fill='#59675f');sources=[]
    for row,id in enumerate(ids):
        top=head+row*rowh
        for col,stage in enumerate(['before','after']):
            file=f'{stage}-diagnostic-pc-{id}-1.webp' if diagnostic else f'{stage}-pc-{time}-{id}.webp';p=OUT/file;im=Image.open(p).convert('RGB');im=ImageOps.fit(im,(w,ih),Image.Resampling.LANCZOS)
            x=12+col*812;d.rectangle((x,top,x+w,top+44),fill='white');d.text((x+12,top+7),(SEAMS if diagnostic else NAMES)[id]+(' · 修复前' if col==0 else ' · 修复后'),font=font(22,True),fill='#2d4e3b');canvas.paste(im,(x,top+44));sources.append({'file':file,'sha256':hashlib.sha256(p.read_bytes()).hexdigest()})
    d.text((12,canvas.height-30),'实际网页 WebGL 画布 · 仅统一裁切 / 缩放和排版 · 手机为模拟',font=font(17),fill='#59675f');canvas.save(OUT/(name+'.jpg'),quality=96,subsampling=0);manifest['sheets'].append({'file':name+'.jpg','sources':sources})
sheet('night-calibrated',['living','kitchen','balconyBasin'],'night','夜晚过亮校正 · 灯能量50% / 室内曝光80%')
sheet('noon-calibrated',['second','bath','balconyBasin'],'noon','正午开灯 · 白色表面和暗部层次')
sheet('overlap-diagnostic',['wardrobeBase','kitchenJoin','chairBoss','doorHeader'],'night','穿插 / 共面重叠诊断 · 原几何深度',True)
(OUT/'captures.json').write_text(json.dumps(records,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
(OUT/'contact-sheets.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
motion={stage:json.loads((ROOT/f'validation/overlap-motion-{stage}.json').read_text(encoding='utf-8')) for stage in ['before','after']};(OUT/'motion.json').write_text(json.dumps(motion,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
overlap=json.loads((ROOT/'validation/exposed-overlap.json').read_text(encoding='utf-8'));(OUT/'geometry-check.json').write_text(json.dumps(overlap,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
stats=[]
for id in ['kitchen','bath','balconyBasin']:
    x=next(c for c in records['before']['cases'][0]['captures'] if c['room']==id and c['time']=='night');y=next(c for c in records['after']['cases'][0]['captures'] if c['room']==id and c['time']=='night');stats.append(f'<tr><td>{NAMES[id]} · 夜晚</td><td>{x["metrics"]["brightFraction"]*100:.2f}%</td><td>{y["metrics"]["brightFraction"]*100:.2f}%</td></tr>')
css=(ROOT/'docs/quality-report/brightness-comparison.html').read_text(encoding='utf-8').split('<style>')[1].split('</style>')[0]
html='''<!doctype html><html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>过曝与模型穿插修复</title><style>CSS .pair{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.pair img{width:100%;display:block}.diagnostic-pair img{background:#ddd} @media(max-width:650px){.pair{gap:6px}}</style></head><body><main><p>杭州 · 璞荟铭庭 / main 当前校正</p><h1>过曝与模型穿插修复</h1><p>本轮实际校正了室内亮度，并处理模型共面重叠。上方查看正常画面，下方用独立诊断色和小幅横移检查衣柜、厨房台面、餐椅与门框。所有图均来自真实网页画布。</p><nav><a href="../?decor=a">打开 main 家装 A</a><a href="brightness-comparison.html">首次灯光 / 曝光试验</a><a href="surface-fixes.html">上一轮曲面与墙顶修复</a><a href="index.html">效果报告首页</a><a href="exposure-overlap/captures.json">相机与亮度数据</a><a href="exposure-overlap/geometry-check.json">几何抽样结果</a><a href="../deployment.json">部署提交</a></nav><div class="notice">灯光基准能量降为修复前的<strong>50%</strong>，室内曝光降为修复前的<strong>80%</strong>。滑块仍表示用户相对强度；已有保存值保持，例如保存的180%仍显示180%，按新基准计算。三维总览和平面曝光保持。新旧画面都使用灯光滑块100%，本轮没有对截图后期压暗。</div><h2>正常画面前后对比</h2><div class="controls" id="device"><button data-device="pc">桌面视口</button><button data-device="mobile">手机视口</button></div><div class="controls" id="time"><button data-time="night">夜晚开灯</button><button data-time="noon">正午开灯</button></div><div class="controls" id="room">ROOM_BUTTONS</div><div class="compare" id="compare"><img id="after" alt="校正后实际网页画布"><img id="before" class="before" alt="同机位校正前画布"><div class="labels"><span>修复前</span><span>修复后</span></div></div><label class="slider">对比位置<input id="split" type="range" min="0" max="100" value="50" aria-label="亮度修复前后对比滑块"></label><p id="caption"></p><div class="pair"><figure><a id="beforeLink"><img id="beforeFull" alt="修复前完整画布"></a><figcaption>修复前 · 点击原图</figcaption></figure><figure><a id="afterLink"><img id="afterFull" alt="修复后完整画布"></a><figcaption>修复后 · 点击原图</figcaption></figure></div><h2>过亮区域变化</h2><p>下表统计桌面同机位中显示亮度≥245/255的像素占比，包含可见灯具；它是用于复核的像素指标，不是实际照度或摄影曝光测量。正常镜面高光、灯具发光和窗外仍可较亮。</p><div class="scroll"><table><thead><tr><th>画面</th><th>修复前</th><th>修复后</th></tr></thead><tbody>STATS</tbody></table></div><figure class="sheet"><a href="exposure-overlap/night-calibrated.jpg"><img src="exposure-overlap/night-calibrated.jpg" loading="lazy" alt="夜晚过曝校正并排总览"></a><figcaption>夜晚 · 客厅 / 厨房 / 阳台台盆</figcaption></figure><figure class="sheet"><a href="exposure-overlap/noon-calibrated.jpg"><img src="exposure-overlap/noon-calibrated.jpg" loading="lazy" alt="正午白色表面过亮校正"></a><figcaption>正午 · 次卧 / 卫生间 / 阳台台盆</figcaption></figure><h2>重叠面与横移诊断</h2><p>以下为<strong>诊断图</strong>：每个实体部件换成固定颜色，去掉材质与光照干扰，几何、深度测试和相机保留原值。衣柜侧板的杂色条纹显示两个表面争夺相同深度；厨房转角原有约30mm的实体交叠。按钮在中心前后各20mm的相机位置间切换，便于复查。</p><div class="controls" id="seam"><button data-seam="wardrobeBase">衣柜侧板与底板</button><button data-seam="kitchenJoin">厨房转角台面</button><button data-seam="chairBoss">餐椅连接</button><button data-seam="doorHeader">门框转角</button></div><label class="slider">横移机位<input id="motion" type="range" min="0" max="2" step="1" value="1" aria-label="诊断相机横移机位"></label><div class="pair diagnostic-pair"><figure><img id="diagnosticBefore" alt="修复前部件深度诊断"><figcaption>修复前 · 诊断配色</figcaption></figure><figure><img id="diagnosticAfter" alt="修复后部件深度诊断"><figcaption>修复后 · 诊断配色</figcaption></figure></div><p id="motionCaption"></p><figure class="sheet"><a href="exposure-overlap/overlap-diagnostic.jpg"><img src="exposure-overlap/overlap-diagnostic.jpg" loading="lazy" alt="衣柜台面餐椅与门框诊断前后总览"></a><figcaption>诊断图：保留原几何和深度；这些颜色不进入看房页面。</figcaption></figure><h2>修复与验证范围</h2><p>衣柜顶/底板嵌入侧板内侧；洗烘柜、台盆柜与厨房柜板按实际板厚收口；餐椅支架端面错开并埋入连接座；书桌横撑缩入立柱。厨房北台面改为一个带真实水槽开孔的闭合实体，并与东侧台面相接。门框竖边终止于横边和门槛内侧，避免转角重复表面。没有使用全局深度偏移、双面材质或移动原墙来掩盖问题。</p><p>对18类重建资产的实际桌面/手机装配表面进行法线射线抽样：原26/27组近共面候选降至0；厨房台面交叠从约30mm变为桌面0mm、手机约0.102mm接缝。654份双档实体闭合检查及两档水槽台面4284条覆盖射线无缺口，装配连通和门扫掠/闭合/通道回归通过。抽样不是任意自交的数学证明。</p><p>本页有48组正常画面前后对比（96张）和4处×3机位×桌面/手机的前后诊断（48张）。每次正常画面等待16位静态照明和房间反射加载完成，再等3帧截图。重新生成124张Cycles照明/AO/反射图；建筑快照和219张旧烘焙保持。64种浏览器/扩展光照状态、设置保存、缺HDR/depth回退、离线与横竖屏检查通过。手机与微信UA、Windows WebKit均为模拟；真机微信仍待验证。单HTML约40MB。</p><footer>2026-11-26 · 本轮校正已进入 main。正式 release 独立保留。</footer></main><script>
const names=NAMES,seams=SEAMS,state={device:'pc',time:'night',room:'balconyBasin',seam:'wardrobeBase',frame:1},$=id=>document.getElementById(id);
function url(stage){return 'exposure-overlap/'+stage+'-'+state.device+'-'+state.time+'-'+state.room+'.webp'}
function update(){for(const key of ['device','time','room','seam'])for(const b of $(key).children)b.setAttribute('aria-pressed',String(b.dataset[key]===state[key]));for(const stage of ['before','after']){$(stage).src=url(stage);$(stage+'Full').src=url(stage);$(stage+'Link').href=url(stage);}$('compare').classList.toggle('mobile',state.device==='mobile');$('caption').textContent=names[state.room]+' · '+(state.time==='night'?'夜晚':'正午')+'开灯 · '+(state.device==='pc'?'桌面':'手机模拟')+'；左修复前、右修复后。';for(const stage of ['Before','After'])$('diagnostic'+stage).src='exposure-overlap/'+stage.toLowerCase()+'-diagnostic-'+state.device+'-'+state.seam+'-'+state.frame+'.webp';$('motionCaption').textContent=seams[state.seam]+' · '+['横移 -20mm','中心机位','横移 +20mm'][state.frame]+' · 诊断色只用于检查重叠面。';}
for(const key of ['device','time','room','seam'])$(key).addEventListener('click',e=>{const b=e.target.closest('button');if(b){state[key]=b.dataset[key];update()}});$('split').addEventListener('input',e=>$('compare').style.setProperty('--split',e.target.value+'%'));$('motion').addEventListener('input',e=>{state.frame=Number(e.target.value);update()});update();
</script></body></html>'''
html=html.replace('CSS',css).replace('ROOM_BUTTONS',''.join(f'<button data-room="{id}">{name}</button>' for id,name in NAMES.items())).replace('STATS',''.join(stats)).replace('NAMES',json.dumps(NAMES,ensure_ascii=False)).replace('SEAMS',json.dumps(SEAMS,ensure_ascii=False))
(ROOT/'docs/quality-report/exposure-overlap.html').write_text(html,encoding='utf-8')
print('Generated exposure and overlap report, 144 source images and 3 sheets')
